SELECT category_group, avg_cost, pct_initech FROM (SELECT CASE WHEN category IN ('Books', 'Sports') THEN 'tier_1' ELSE 'other' END AS category_group, AVG(cost) AS avg_cost, ROUND((100 * SUM(CASE WHEN brand = 'Initech' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_initech FROM products GROUP BY CASE WHEN category IN ('Books', 'Sports') THEN 'tier_1' ELSE 'other' END) AS sub WHERE avg_cost < 510 ORDER BY pct_initech DESC, category_group LIMIT 3;
